// Centralized configuration for ROYA Ecosystem
const region = $json.region || "MX";
const config = {
  MX: {
    timezone: "America/Mexico_City",
    language: "es-MX",
    allowed_hours: { start: 9, end: 20 }
  },
  US: {
    timezone: "America/New_York",
    language: "en-US",
    allowed_hours: { start: 8, end: 21 }
  }
};

return {
  json: {
    region: region,
    config: config[region] || config.MX,
    schema_version: "v1"
  }
};

// Standard Lead Schema v1 Factory
const input = $json.body || $json;
return {
  json: {
    lead_id: input.lead_id || "new-uuid",
    phone: input.phone,
    source: input.source || "unknown",
    status: "new",
    created_at: new Date().toISOString(),
    schema_version: "v1",
    metadata: input.metadata || {}
  }
};
